-- FCA-AI database setup: all migrations in order. GENERATED by `npm run db:setup-sql` — do not edit.
-- Run once on a NEW Supabase project (SQL editor → paste → Run). For later changes use `supabase db push`.

-- ===== 20261113000001_core_schema.sql =====
-- FCA-AI core schema
-- Schema version 1. Every user-owned table carries user_id and is protected by RLS
-- (see 20261113000002_rls.sql). Child tables use composite foreign keys
-- (parent_id, user_id) -> parent(id, user_id) so rows can never be attached to
-- another user's data.

create extension if not exists pgcrypto with schema extensions;

-- ---------------------------------------------------------------------------
-- Enumerations
-- ---------------------------------------------------------------------------
create type public.education_level as enum (
  'secondary', 'undergraduate', 'postgraduate', 'professional', 'exam_candidate', 'independent', 'other'
);
create type public.subject_kind as enum ('subject', 'course', 'examination');
create type public.folder_kind as enum ('folder', 'collection');
create type public.material_file_type as enum ('pdf', 'docx', 'txt');
create type public.material_status as enum (
  'uploaded', 'queued', 'extracting', 'analysing', 'structuring', 'ready', 'failed'
);
create type public.job_status as enum ('queued', 'running', 'succeeded', 'failed', 'cancelled');
create type public.plan_mode as enum ('individual', 'combined');
create type public.plan_status as enum ('draft', 'active', 'completed', 'archived');
create type public.workload_preference as enum ('light', 'balanced', 'intensive');
create type public.session_kind as enum ('study', 'revision', 'assessment');
create type public.session_status as enum ('scheduled', 'in_progress', 'completed', 'missed', 'rescheduled');
create type public.task_status as enum ('pending', 'in_progress', 'completed', 'skipped');
create type public.highlight_color as enum ('lime', 'yellow', 'green', 'blue', 'pink', 'orange');
create type public.conversation_mode as enum ('general', 'grounded');
create type public.message_role as enum ('user', 'assistant');
create type public.quiz_kind as enum ('daily', 'practice', 'mock');
create type public.quiz_status as enum ('generating', 'ready', 'failed');
create type public.question_type as enum ('mcq', 'true_false', 'fill_blank', 'short_answer', 'theory');
create type public.attempt_status as enum ('in_progress', 'submitted', 'graded');
create type public.flashcard_origin as enum ('material', 'section', 'definition', 'concept', 'quiz_mistake', 'manual');
create type public.flashcard_rating as enum ('difficult', 'practice', 'know');
create type public.activity_kind as enum (
  'reading', 'task_completed', 'session_completed', 'quiz_completed', 'flashcard_review', 'ai_question', 'material_uploaded'
);
create type public.notification_kind as enum (
  'study_reminder', 'upcoming_session', 'unfinished_task', 'quiz_reminder', 'streak', 'plan_changed', 'achievement', 'processing', 'system'
);
create type public.subscription_plan as enum ('free', 'premium');
create type public.subscription_status as enum ('active', 'trialing', 'past_due', 'cancelled', 'incomplete');
create type public.billing_provider as enum ('none', 'stripe', 'paystack');

-- ---------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------
create or replace function public.set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- ---------------------------------------------------------------------------
-- 1. profiles
-- ---------------------------------------------------------------------------
create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  preferred_name text check (char_length(preferred_name) between 1 and 60),
  full_name text check (char_length(full_name) <= 120),
  avatar_url text,
  education_level public.education_level,
  learning_goals text[] not null default '{}',
  daily_study_minutes integer not null default 60 check (daily_study_minutes between 10 and 720),
  preferred_study_time text check (preferred_study_time in ('morning', 'afternoon', 'evening', 'night', 'flexible')),
  timezone text not null default 'UTC' check (char_length(timezone) between 1 and 64),
  notification_prefs jsonb not null default
    '{"daily_reminder": true, "reminder_time": "18:00", "sessions": true, "quizzes": true, "streaks": true, "achievements": true, "plan_changes": true, "email": false}'::jsonb,
  reading_prefs jsonb not null default
    '{"font_size": 18, "line_height": 1.7, "theme": "dark", "focus_mode": false}'::jsonb,
  theme text not null default 'dark' check (theme in ('dark', 'light', 'system')),
  xp integer not null default 0 check (xp >= 0),
  onboarding_completed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create trigger profiles_updated_at before update on public.profiles
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- 2. subjects
-- ---------------------------------------------------------------------------
create table public.subjects (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  name text not null check (char_length(name) between 1 and 120),
  kind public.subject_kind not null default 'subject',
  color text check (color ~ '^#[0-9A-Fa-f]{6}$'),
  exam_date date,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (id, user_id),
  unique (user_id, kind, name)
);
create index subjects_user_idx on public.subjects (user_id);
create trigger subjects_updated_at before update on public.subjects
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- 3. folders
-- ---------------------------------------------------------------------------
create table public.folders (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  parent_id uuid,
  subject_id uuid,
  name text not null check (char_length(name) between 1 and 120),
  kind public.folder_kind not null default 'folder',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (id, user_id),
  foreign key (parent_id, user_id) references public.folders (id, user_id) on delete cascade,
  foreign key (subject_id, user_id) references public.subjects (id, user_id) on delete set null (subject_id),
  check (parent_id is null or parent_id <> id)
);
create index folders_user_idx on public.folders (user_id);
create index folders_parent_idx on public.folders (parent_id);
create trigger folders_updated_at before update on public.folders
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- 4. materials
-- ---------------------------------------------------------------------------
create table public.materials (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  subject_id uuid,
  folder_id uuid,
  title text not null check (char_length(title) between 1 and 300),
  original_filename text not null check (char_length(original_filename) between 1 and 300),
  file_type public.material_file_type not null,
  mime_type text not null,
  size_bytes bigint not null check (size_bytes > 0),
  storage_path text not null unique,
  checksum_sha256 text check (checksum_sha256 ~ '^[0-9a-f]{64}$'),
  page_count integer check (page_count >= 0),
  word_count integer check (word_count >= 0),
  status public.material_status not null default 'uploaded',
  status_detail text,
  processing_error text,
  processing_progress smallint not null default 0 check (processing_progress between 0 and 100),
  last_opened_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (id, user_id),
  foreign key (subject_id, user_id) references public.subjects (id, user_id) on delete set null (subject_id),
  foreign key (folder_id, user_id) references public.folders (id, user_id) on delete set null (folder_id)
);
create index materials_user_created_idx on public.materials (user_id, created_at desc);
create index materials_user_status_idx on public.materials (user_id, status);
create index materials_user_checksum_idx on public.materials (user_id, checksum_sha256);
create index materials_subject_idx on public.materials (subject_id);
create index materials_folder_idx on public.materials (folder_id);
create trigger materials_updated_at before update on public.materials
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- 5. material_pages
-- ---------------------------------------------------------------------------
create table public.material_pages (
  id uuid primary key default gen_random_uuid(),
  material_id uuid not null,
  user_id uuid not null references auth.users (id) on delete cascade,
  page_number integer not null check (page_number >= 1),
  content text not null default '',
  char_count integer generated always as (char_length(content)) stored,
  ocr_used boolean not null default false,
  created_at timestamptz not null default now(),
  unique (material_id, page_number),
  foreign key (material_id, user_id) references public.materials (id, user_id) on delete cascade
);
create index material_pages_user_idx on public.material_pages (user_id);

-- ---------------------------------------------------------------------------
-- 6. document_processing_jobs
-- ---------------------------------------------------------------------------
create table public.document_processing_jobs (
  id uuid primary key default gen_random_uuid(),
  material_id uuid not null,
  user_id uuid not null references auth.users (id) on delete cascade,
  status public.job_status not null default 'queued',
  stage public.material_status not null default 'queued',
  progress smallint not null default 0 check (progress between 0 and 100),
  attempts integer not null default 0 check (attempts >= 0),
  max_attempts integer not null default 3 check (max_attempts between 1 and 10),
  error text,
  run_after timestamptz not null default now(),
  locked_at timestamptz,
  locked_by text,
  started_at timestamptz,
  finished_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  foreign key (material_id, user_id) references public.materials (id, user_id) on delete cascade
);
create index processing_jobs_queue_idx on public.document_processing_jobs (status, run_after)
  where status in ('queued', 'running');
create index processing_jobs_material_idx on public.document_processing_jobs (material_id);
create index processing_jobs_user_idx on public.document_processing_jobs (user_id);
create trigger processing_jobs_updated_at before update on public.document_processing_jobs
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- 7. document_sections
-- ---------------------------------------------------------------------------
create table public.document_sections (
  id uuid primary key default gen_random_uuid(),
  material_id uuid not null,
  user_id uuid not null references auth.users (id) on delete cascade,
  parent_id uuid,
  level smallint not null check (level between 1 and 3), -- 1 chapter, 2 subtopic, 3 learning unit
  position integer not null check (position >= 0),
  title text not null check (char_length(title) between 1 and 300),
  summary text,
  start_page integer not null check (start_page >= 1),
  end_page integer not null,
  estimated_minutes integer check (estimated_minutes >= 0),
  complexity smallint check (complexity between 1 and 5),
  learning_objectives text[] not null default '{}',
  key_concepts text[] not null default '{}',
  created_at timestamptz not null default now(),
  unique (id, user_id),
  check (end_page >= start_page),
  foreign key (material_id, user_id) references public.materials (id, user_id) on delete cascade,
  foreign key (parent_id, user_id) references public.document_sections (id, user_id) on delete cascade
);
create index sections_material_idx on public.document_sections (material_id, level, position);
create index sections_parent_idx on public.document_sections (parent_id);
create index sections_user_idx on public.document_sections (user_id);

-- ---------------------------------------------------------------------------
-- 8. study_plans  /  9. study_plan_materials
-- ---------------------------------------------------------------------------
create table public.study_plans (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  title text not null check (char_length(title) between 1 and 200),
  mode public.plan_mode not null,
  status public.plan_status not null default 'draft',
  start_date date not null,
  deadline date not null,
  daily_minutes integer not null check (daily_minutes between 10 and 720),
  study_days smallint[] not null default '{1,2,3,4,5}' check (study_days <@ '{0,1,2,3,4,5,6}'::smallint[] and cardinality(study_days) >= 1),
  preferred_time text,
  workload public.workload_preference not null default 'balanced',
  version integer not null default 1,
  generation_meta jsonb not null default '{}'::jsonb,
  completed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (id, user_id),
  check (deadline >= start_date)
);
create index study_plans_user_idx on public.study_plans (user_id, status);
create trigger study_plans_updated_at before update on public.study_plans
  for each row execute function public.set_updated_at();

create table public.study_plan_materials (
  plan_id uuid not null,
  material_id uuid not null,
  user_id uuid not null references auth.users (id) on delete cascade,
  position integer not null default 0,
  created_at timestamptz not null default now(),
  primary key (plan_id, material_id),
  foreign key (plan_id, user_id) references public.study_plans (id, user_id) on delete cascade,
  foreign key (material_id, user_id) references public.materials (id, user_id) on delete cascade
);
create index plan_materials_material_idx on public.study_plan_materials (material_id);
create index plan_materials_user_idx on public.study_plan_materials (user_id);

-- ---------------------------------------------------------------------------
-- 10. study_sessions  /  11. study_tasks
-- ---------------------------------------------------------------------------
create table public.study_sessions (
  id uuid primary key default gen_random_uuid(),
  plan_id uuid not null,
  user_id uuid not null references auth.users (id) on delete cascade,
  scheduled_date date not null,
  starts_at timestamptz,
  planned_minutes integer not null check (planned_minutes between 1 and 720),
  kind public.session_kind not null default 'study',
  status public.session_status not null default 'scheduled',
  title text not null,
  objectives text[] not null default '{}',
  rescheduled_from uuid,
  completed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (id, user_id),
  foreign key (plan_id, user_id) references public.study_plans (id, user_id) on delete cascade,
  foreign key (rescheduled_from, user_id) references public.study_sessions (id, user_id) on delete set null (rescheduled_from)
);
create index study_sessions_user_date_idx on public.study_sessions (user_id, scheduled_date);
create index study_sessions_plan_idx on public.study_sessions (plan_id, scheduled_date);
create trigger study_sessions_updated_at before update on public.study_sessions
  for each row execute function public.set_updated_at();

create table public.study_tasks (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null,
  plan_id uuid not null,
  user_id uuid not null references auth.users (id) on delete cascade,
  material_id uuid,
  section_id uuid,
  position integer not null default 0,
  title text not null,
  start_page integer check (start_page >= 1),
  end_page integer,
  estimated_minutes integer not null default 0 check (estimated_minutes >= 0),
  status public.task_status not null default 'pending',
  completed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (id, user_id),
  check (end_page is null or start_page is null or end_page >= start_page),
  foreign key (session_id, user_id) references public.study_sessions (id, user_id) on delete cascade,
  foreign key (plan_id, user_id) references public.study_plans (id, user_id) on delete cascade,
  foreign key (material_id, user_id) references public.materials (id, user_id) on delete cascade,
  foreign key (section_id, user_id) references public.document_sections (id, user_id) on delete set null (section_id)
);
create index study_tasks_session_idx on public.study_tasks (session_id, position);
create index study_tasks_user_status_idx on public.study_tasks (user_id, status);
create index study_tasks_material_idx on public.study_tasks (material_id);
create trigger study_tasks_updated_at before update on public.study_tasks
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- 12. reading_progress / 13. bookmarks / 14. highlights / 15. notes
-- ---------------------------------------------------------------------------
create table public.reading_progress (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  material_id uuid not null,
  current_page integer not null default 1 check (current_page >= 1),
  scroll_offset real not null default 0 check (scroll_offset between 0 and 1),
  pages_read integer[] not null default '{}',
  completed_section_ids uuid[] not null default '{}',
  percent_complete numeric(5, 2) not null default 0 check (percent_complete between 0 and 100),
  total_seconds integer not null default 0 check (total_seconds >= 0),
  last_read_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, material_id),
  foreign key (material_id, user_id) references public.materials (id, user_id) on delete cascade
);
create index reading_progress_last_read_idx on public.reading_progress (user_id, last_read_at desc);
create trigger reading_progress_updated_at before update on public.reading_progress
  for each row execute function public.set_updated_at();

create table public.bookmarks (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  material_id uuid not null,
  page_number integer not null check (page_number >= 1),
  label text check (char_length(label) <= 200),
  created_at timestamptz not null default now(),
  unique (user_id, material_id, page_number),
  foreign key (material_id, user_id) references public.materials (id, user_id) on delete cascade
);

create table public.highlights (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  material_id uuid not null,
  section_id uuid,
  page_number integer not null check (page_number >= 1),
  text text not null check (char_length(text) between 1 and 5000),
  color public.highlight_color not null default 'lime',
  anchor jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (id, user_id),
  foreign key (material_id, user_id) references public.materials (id, user_id) on delete cascade,
  foreign key (section_id, user_id) references public.document_sections (id, user_id) on delete set null (section_id)
);
create index highlights_material_idx on public.highlights (user_id, material_id, page_number);
create index highlights_text_search_idx on public.highlights using gin (to_tsvector('simple', text));
create trigger highlights_updated_at before update on public.highlights
  for each row execute function public.set_updated_at();

create table public.notes (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  material_id uuid,
  section_id uuid,
  highlight_id uuid,
  page_number integer check (page_number >= 1),
  title text check (char_length(title) <= 200),
  body text not null check (char_length(body) between 1 and 20000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  foreign key (material_id, user_id) references public.materials (id, user_id) on delete cascade,
  foreign key (section_id, user_id) references public.document_sections (id, user_id) on delete set null (section_id),
  foreign key (highlight_id, user_id) references public.highlights (id, user_id) on delete set null (highlight_id)
);
create index notes_user_material_idx on public.notes (user_id, material_id, page_number);
create trigger notes_updated_at before update on public.notes
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- 16. ai_conversations / 17. ai_messages
-- ---------------------------------------------------------------------------
create table public.ai_conversations (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  mode public.conversation_mode not null default 'general',
  material_id uuid,
  section_id uuid,
  title text not null default 'New conversation' check (char_length(title) between 1 and 200),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (id, user_id),
  foreign key (material_id, user_id) references public.materials (id, user_id) on delete set null (material_id),
  foreign key (section_id, user_id) references public.document_sections (id, user_id) on delete set null (section_id),
  check (mode = 'general' or material_id is not null or section_id is not null)
);
create index ai_conversations_user_idx on public.ai_conversations (user_id, updated_at desc);
create trigger ai_conversations_updated_at before update on public.ai_conversations
  for each row execute function public.set_updated_at();

create table public.ai_messages (
  id uuid primary key default gen_random_uuid(),
  conversation_id uuid not null,
  user_id uuid not null references auth.users (id) on delete cascade,
  role public.message_role not null,
  content text not null check (char_length(content) between 1 and 100000),
  citations jsonb not null default '[]'::jsonb,
  model text,
  input_tokens integer,
  output_tokens integer,
  created_at timestamptz not null default now(),
  foreign key (conversation_id, user_id) references public.ai_conversations (id, user_id) on delete cascade
);
create index ai_messages_conversation_idx on public.ai_messages (conversation_id, created_at);

-- ---------------------------------------------------------------------------
-- 18-21. quizzes, questions, attempts, answers
-- ---------------------------------------------------------------------------
create table public.quizzes (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  session_id uuid,
  plan_id uuid,
  material_id uuid,
  title text not null check (char_length(title) between 1 and 200),
  kind public.quiz_kind not null default 'practice',
  status public.quiz_status not null default 'generating',
  source_section_ids uuid[] not null default '{}',
  time_limit_seconds integer check (time_limit_seconds between 30 and 14400),
  question_count integer not null default 0,
  error text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (id, user_id),
  foreign key (session_id, user_id) references public.study_sessions (id, user_id) on delete set null (session_id),
  foreign key (plan_id, user_id) references public.study_plans (id, user_id) on delete set null (plan_id),
  foreign key (material_id, user_id) references public.materials (id, user_id) on delete set null (material_id)
);
create index quizzes_user_idx on public.quizzes (user_id, created_at desc);
create index quizzes_session_idx on public.quizzes (session_id);
create trigger quizzes_updated_at before update on public.quizzes
  for each row execute function public.set_updated_at();

create table public.quiz_questions (
  id uuid primary key default gen_random_uuid(),
  quiz_id uuid not null,
  user_id uuid not null references auth.users (id) on delete cascade,
  position integer not null check (position >= 0),
  type public.question_type not null,
  prompt text not null,
  options jsonb not null default '[]'::jsonb,
  correct_answer jsonb not null,
  explanation text,
  topic text,
  section_id uuid,
  source_material_id uuid,
  source_page integer,
  points numeric(5, 2) not null default 1 check (points > 0),
  created_at timestamptz not null default now(),
  unique (id, user_id),
  unique (quiz_id, position),
  foreign key (quiz_id, user_id) references public.quizzes (id, user_id) on delete cascade,
  foreign key (section_id, user_id) references public.document_sections (id, user_id) on delete set null (section_id),
  foreign key (source_material_id, user_id) references public.materials (id, user_id) on delete set null (source_material_id)
);

create table public.quiz_attempts (
  id uuid primary key default gen_random_uuid(),
  quiz_id uuid not null,
  user_id uuid not null references auth.users (id) on delete cascade,
  status public.attempt_status not null default 'in_progress',
  started_at timestamptz not null default now(),
  submitted_at timestamptz,
  score numeric(7, 2),
  max_score numeric(7, 2),
  percent numeric(5, 2) check (percent between 0 and 100),
  feedback jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  unique (id, user_id),
  foreign key (quiz_id, user_id) references public.quizzes (id, user_id) on delete cascade
);
create index quiz_attempts_user_idx on public.quiz_attempts (user_id, submitted_at desc);
create index quiz_attempts_quiz_idx on public.quiz_attempts (quiz_id);

create table public.quiz_answers (
  id uuid primary key default gen_random_uuid(),
  attempt_id uuid not null,
  question_id uuid not null,
  user_id uuid not null references auth.users (id) on delete cascade,
  answer jsonb,
  is_correct boolean,
  points_awarded numeric(5, 2),
  feedback text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (attempt_id, question_id),
  foreign key (attempt_id, user_id) references public.quiz_attempts (id, user_id) on delete cascade,
  foreign key (question_id, user_id) references public.quiz_questions (id, user_id) on delete cascade
);
create trigger quiz_answers_updated_at before update on public.quiz_answers
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- 22. flashcards / 23. flashcard_reviews
-- ---------------------------------------------------------------------------
create table public.flashcards (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  material_id uuid,
  section_id uuid,
  source_question_id uuid,
  origin public.flashcard_origin not null default 'material',
  front text not null check (char_length(front) between 1 and 2000),
  back text not null check (char_length(back) between 1 and 4000),
  explanation text,
  source_page integer,
  ease_factor numeric(4, 2) not null default 2.5 check (ease_factor between 1.3 and 3.0),
  interval_days integer not null default 0 check (interval_days >= 0),
  repetitions integer not null default 0 check (repetitions >= 0),
  due_at timestamptz not null default now(),
  suspended boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (id, user_id),
  foreign key (material_id, user_id) references public.materials (id, user_id) on delete cascade,
  foreign key (section_id, user_id) references public.document_sections (id, user_id) on delete set null (section_id),
  foreign key (source_question_id, user_id) references public.quiz_questions (id, user_id) on delete set null (source_question_id)
);
create index flashcards_due_idx on public.flashcards (user_id, due_at) where not suspended;
create trigger flashcards_updated_at before update on public.flashcards
  for each row execute function public.set_updated_at();

create table public.flashcard_reviews (
  id uuid primary key default gen_random_uuid(),
  flashcard_id uuid not null,
  user_id uuid not null references auth.users (id) on delete cascade,
  rating public.flashcard_rating not null,
  previous_interval_days integer not null,
  new_interval_days integer not null,
  ease_factor numeric(4, 2) not null,
  reviewed_at timestamptz not null default now(),
  foreign key (flashcard_id, user_id) references public.flashcards (id, user_id) on delete cascade
);
create index flashcard_reviews_user_idx on public.flashcard_reviews (user_id, reviewed_at desc);

-- ---------------------------------------------------------------------------
-- 24-27. streaks, achievements, activity
-- ---------------------------------------------------------------------------
create table public.study_streaks (
  user_id uuid primary key references auth.users (id) on delete cascade,
  current_streak integer not null default 0 check (current_streak >= 0),
  longest_streak integer not null default 0 check (longest_streak >= 0),
  last_qualifying_date date,
  updated_at timestamptz not null default now()
);

create table public.achievements (
  id uuid primary key default gen_random_uuid(),
  code text not null unique check (code ~ '^[a-z0-9_]+$'),
  name text not null,
  description text not null,
  icon text not null default 'trophy',
  xp integer not null default 0 check (xp >= 0),
  criteria jsonb not null default '{}'::jsonb,
  sort_order integer not null default 0,
  created_at timestamptz not null default now()
);

create table public.user_achievements (
  user_id uuid not null references auth.users (id) on delete cascade,
  achievement_id uuid not null references public.achievements (id) on delete cascade,
  earned_at timestamptz not null default now(),
  primary key (user_id, achievement_id)
);

create table public.study_activity (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  kind public.activity_kind not null,
  activity_date date not null, -- local date in the user's time zone
  minutes integer not null default 0 check (minutes between 0 and 1440),
  material_id uuid,
  reference_id uuid,
  qualifies_for_streak boolean not null default false,
  xp_awarded integer not null default 0 check (xp_awarded >= 0),
  created_at timestamptz not null default now(),
  foreign key (material_id, user_id) references public.materials (id, user_id) on delete set null (material_id)
);
create index study_activity_user_date_idx on public.study_activity (user_id, activity_date desc);
create index study_activity_user_kind_idx on public.study_activity (user_id, kind);

-- ---------------------------------------------------------------------------
-- 28. notifications
-- ---------------------------------------------------------------------------
create table public.notifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  kind public.notification_kind not null,
  title text not null check (char_length(title) between 1 and 200),
  body text check (char_length(body) <= 2000),
  link text check (link is null or link ~ '^/'),
  scheduled_for timestamptz not null default now(),
  read_at timestamptz,
  created_at timestamptz not null default now()
);
create index notifications_user_idx on public.notifications (user_id, scheduled_for desc);
create index notifications_unread_idx on public.notifications (user_id) where read_at is null;

-- ---------------------------------------------------------------------------
-- 29. subscriptions
-- ---------------------------------------------------------------------------
create table public.subscriptions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null unique references auth.users (id) on delete cascade,
  plan public.subscription_plan not null default 'free',
  status public.subscription_status not null default 'active',
  provider public.billing_provider not null default 'none',
  provider_customer_id text,
  provider_subscription_id text,
  current_period_end timestamptz,
  cancel_at_period_end boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (provider, provider_subscription_id)
);
create trigger subscriptions_updated_at before update on public.subscriptions
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Supporting: AI usage metering & rate limiting
-- ---------------------------------------------------------------------------
create table public.ai_usage_events (
  id bigint generated always as identity primary key,
  user_id uuid not null references auth.users (id) on delete cascade,
  feature text not null,
  model text,
  input_tokens integer not null default 0,
  output_tokens integer not null default 0,
  created_at timestamptz not null default now()
);
create index ai_usage_user_time_idx on public.ai_usage_events (user_id, created_at desc);
create index ai_usage_user_feature_idx on public.ai_usage_events (user_id, feature, created_at desc);

create table public.rate_limit_buckets (
  key text not null,
  window_start timestamptz not null,
  count integer not null default 0,
  primary key (key, window_start)
);

-- ===== 20261113000002_rls.sql =====
-- FCA-AI Row Level Security
--
-- Access classes:
--   owner_crud      : the owner may select / insert / update / delete their own rows.
--   owner_read      : the owner may only read; writes happen through trusted server
--                     code (service role) or SECURITY DEFINER functions. Used for data
--                     that must not be fabricated by the client (AI output, quiz
--                     results, streaks, XP, subscriptions, processing output).
--   owner_read_write_no_insert : notifications — owner can read, mark read, delete.
-- anon has no access to application tables at all.

-- Enable RLS everywhere (also on tables nobody but the service role may touch).
do $$
declare t text;
begin
  foreach t in array array[
    'profiles','subjects','folders','materials','material_pages','document_processing_jobs',
    'document_sections','study_plans','study_plan_materials','study_sessions','study_tasks',
    'reading_progress','bookmarks','highlights','notes','ai_conversations','ai_messages',
    'quizzes','quiz_questions','quiz_attempts','quiz_answers','flashcards','flashcard_reviews',
    'study_streaks','achievements','user_achievements','study_activity','notifications',
    'subscriptions','ai_usage_events','rate_limit_buckets'
  ] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon', t);
  end loop;
end $$;

-- owner_crud tables -----------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array[
    'subjects','folders','materials','study_plans','study_plan_materials','study_sessions',
    'study_tasks','reading_progress','bookmarks','highlights','notes','ai_conversations',
    'flashcards'
  ] loop
    execute format($f$create policy "%1$s_select_own" on public.%1$I for select to authenticated
      using (user_id = (select auth.uid()))$f$, t);
    execute format($f$create policy "%1$s_insert_own" on public.%1$I for insert to authenticated
      with check (user_id = (select auth.uid()))$f$, t);
    execute format($f$create policy "%1$s_update_own" on public.%1$I for update to authenticated
      using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()))$f$, t);
    execute format($f$create policy "%1$s_delete_own" on public.%1$I for delete to authenticated
      using (user_id = (select auth.uid()))$f$, t);
  end loop;
end $$;

-- owner_read tables ------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array[
    'material_pages','document_processing_jobs','document_sections','ai_messages','quizzes',
    'quiz_questions','quiz_attempts','quiz_answers','study_streaks','user_achievements',
    'study_activity','subscriptions','ai_usage_events','flashcard_reviews'
  ] loop
    execute format($f$create policy "%1$s_select_own" on public.%1$I for select to authenticated
      using (user_id = (select auth.uid()))$f$, t);
    execute format('revoke insert, update, delete, truncate on public.%I from authenticated', t);
  end loop;
end $$;

-- The student writes their own question to a conversation; assistant replies are
-- written by the server after the model responds.
grant insert on public.ai_messages to authenticated;
create policy "ai_messages_insert_own_user_role" on public.ai_messages for insert to authenticated
  with check (user_id = (select auth.uid()) and role = 'user');

-- Flashcard reviews are a log written by the student while revising.
grant insert on public.flashcard_reviews to authenticated;
create policy "flashcard_reviews_insert_own" on public.flashcard_reviews for insert to authenticated
  with check (user_id = (select auth.uid()));

-- Quiz questions: correct answers & explanations are hidden at column level until
-- an attempt is submitted (exposed through public.get_attempt_review()).
revoke select on public.quiz_questions from authenticated;
grant select (id, quiz_id, user_id, position, type, prompt, options, topic, section_id,
              source_material_id, source_page, points, created_at)
  on public.quiz_questions to authenticated;

-- profiles ---------------------------------------------------------------------
create policy "profiles_select_own" on public.profiles for select to authenticated
  using (id = (select auth.uid()));
create policy "profiles_update_own" on public.profiles for update to authenticated
  using (id = (select auth.uid())) with check (id = (select auth.uid()));
-- Rows are created by the auth trigger; XP is only changed by record_study_activity().
revoke insert, delete, truncate on public.profiles from authenticated;
revoke update on public.profiles from authenticated;
grant update (preferred_name, full_name, avatar_url, education_level, learning_goals,
              daily_study_minutes, preferred_study_time, timezone, notification_prefs,
              reading_prefs, theme, onboarding_completed_at)
  on public.profiles to authenticated;

-- notifications -----------------------------------------------------------------
create policy "notifications_select_own" on public.notifications for select to authenticated
  using (user_id = (select auth.uid()));
create policy "notifications_update_own" on public.notifications for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy "notifications_delete_own" on public.notifications for delete to authenticated
  using (user_id = (select auth.uid()));
revoke insert, truncate on public.notifications from authenticated;
revoke update on public.notifications from authenticated;
grant update (read_at) on public.notifications to authenticated;

-- achievements catalogue: readable by any signed-in student -----------------------
create policy "achievements_read_all" on public.achievements for select to authenticated using (true);
revoke insert, update, delete, truncate on public.achievements from authenticated;

-- rate_limit_buckets: no policies -> only service role / definer functions.
revoke all on public.rate_limit_buckets from authenticated;

-- ===== 20261113000003_functions.sql =====
-- FCA-AI server-side functions

-- Materials: students may rename / organise / mark opened, but processing fields are
-- owned by the processing pipeline.
revoke update on public.materials from authenticated;
grant update (title, subject_id, folder_id, last_opened_at) on public.materials to authenticated;

-- ---------------------------------------------------------------------------
-- New user bootstrap: profile, streak row, free subscription.
-- ---------------------------------------------------------------------------
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_name text := nullif(trim(coalesce(new.raw_user_meta_data ->> 'preferred_name',
                                      new.raw_user_meta_data ->> 'full_name',
                                      new.raw_user_meta_data ->> 'name', '')), '');
begin
  insert into public.profiles (id, preferred_name, full_name, avatar_url)
  values (
    new.id,
    left(v_name, 60),
    left(nullif(trim(coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name', '')), ''), 120),
    new.raw_user_meta_data ->> 'avatar_url'
  )
  on conflict (id) do nothing;

  insert into public.study_streaks (user_id) values (new.id) on conflict do nothing;
  insert into public.subscriptions (user_id) values (new.id) on conflict do nothing;
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- ---------------------------------------------------------------------------
-- Local date helper (user's time zone; falls back to UTC on invalid zones).
-- ---------------------------------------------------------------------------
create or replace function public.user_local_date(p_user_id uuid, p_at timestamptz default now())
returns date
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_tz text;
begin
  select timezone into v_tz from public.profiles where id = p_user_id;
  begin
    return (p_at at time zone coalesce(v_tz, 'UTC'))::date;
  exception when others then
    return (p_at at time zone 'UTC')::date;
  end;
end;
$$;
revoke execute on function public.user_local_date(uuid, timestamptz) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Activity ledger + streak + XP + achievements.
--
-- Streak rule: a day counts only when the student completes a meaningful learning
-- activity: an assigned study task, a study session or an assessment. Each such
-- activity must reference a real, completed row owned by the caller and may be
-- recorded only once. Opening the app or reading alone never extends a streak.
-- XP is capped per day to avoid rewarding unhealthy marathon sessions.
-- ---------------------------------------------------------------------------
create unique index study_activity_once_per_reference
  on public.study_activity (user_id, kind, reference_id)
  where reference_id is not null and kind in ('task_completed', 'session_completed', 'quiz_completed', 'material_uploaded');

create or replace function public.record_study_activity(
  p_kind public.activity_kind,
  p_minutes integer default 0,
  p_material_id uuid default null,
  p_reference_id uuid default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_today date;
  v_minutes integer := greatest(0, least(coalesce(p_minutes, 0), 240));
  v_qualifies boolean := p_kind in ('task_completed', 'session_completed', 'quiz_completed');
  v_xp integer;
  v_xp_today integer;
  v_daily_cap constant integer := 300;
  v_streak public.study_streaks%rowtype;
  v_new_achievements jsonb := '[]'::jsonb;
  v_ach record;
  v_valid boolean := true;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- Qualifying activities must point at real, completed work owned by the caller.
  if p_kind = 'task_completed' then
    select exists (select 1 from public.study_tasks
                   where id = p_reference_id and user_id = v_uid and status = 'completed') into v_valid;
  elsif p_kind = 'session_completed' then
    select exists (select 1 from public.study_sessions
                   where id = p_reference_id and user_id = v_uid and status = 'completed') into v_valid;
  elsif p_kind = 'quiz_completed' then
    select exists (select 1 from public.quiz_attempts
                   where id = p_reference_id and user_id = v_uid and status in ('submitted', 'graded')) into v_valid;
  elsif p_kind = 'material_uploaded' then
    select exists (select 1 from public.materials
                   where id = p_reference_id and user_id = v_uid) into v_valid;
  end if;
  if not v_valid then
    raise exception 'activity reference is not a completed item owned by the caller' using errcode = '22023';
  end if;

  if p_material_id is not null and not exists (
    select 1 from public.materials where id = p_material_id and user_id = v_uid
  ) then
    raise exception 'material not found' using errcode = '22023';
  end if;

  v_today := public.user_local_date(v_uid);

  v_xp := case p_kind
    when 'reading' then least(v_minutes / 5, 12)
    when 'task_completed' then 20
    when 'session_completed' then 50
    when 'quiz_completed' then 30
    when 'flashcard_review' then 2
    when 'material_uploaded' then 10
    else 0
  end;

  select coalesce(sum(xp_awarded), 0) into v_xp_today
  from public.study_activity where user_id = v_uid and activity_date = v_today;
  v_xp := greatest(0, least(v_xp, v_daily_cap - v_xp_today));

  begin
    insert into public.study_activity (user_id, kind, activity_date, minutes, material_id, reference_id,
                                       qualifies_for_streak, xp_awarded)
    values (v_uid, p_kind, v_today, v_minutes, p_material_id, p_reference_id, v_qualifies, v_xp);
  exception when unique_violation then
    -- Already recorded: idempotent no-op.
    select * into v_streak from public.study_streaks where user_id = v_uid;
    return jsonb_build_object('recorded', false, 'xp_awarded', 0,
                              'current_streak', coalesce(v_streak.current_streak, 0),
                              'new_achievements', '[]'::jsonb);
  end;

  insert into public.study_streaks (user_id) values (v_uid) on conflict do nothing;
  select * into v_streak from public.study_streaks where user_id = v_uid for update;

  if v_qualifies and (v_streak.last_qualifying_date is distinct from v_today) then
    if v_streak.last_qualifying_date = v_today - 1 then
      v_streak.current_streak := v_streak.current_streak + 1;
    else
      v_streak.current_streak := 1;
    end if;
    v_streak.longest_streak := greatest(v_streak.longest_streak, v_streak.current_streak);
    v_streak.last_qualifying_date := v_today;
    update public.study_streaks
       set current_streak = v_streak.current_streak,
           longest_streak = v_streak.longest_streak,
           last_qualifying_date = v_streak.last_qualifying_date,
           updated_at = now()
     where user_id = v_uid;
  end if;

  -- Achievements
  for v_ach in
    select a.* from public.achievements a
    where not exists (select 1 from public.user_achievements ua
                      where ua.user_id = v_uid and ua.achievement_id = a.id)
  loop
    if (case v_ach.criteria ->> 'type'
          when 'qualifying_activities' then
            (select count(*) from public.study_activity
              where user_id = v_uid and qualifies_for_streak) >= (v_ach.criteria ->> 'count')::int
          when 'streak' then v_streak.current_streak >= (v_ach.criteria ->> 'days')::int
          when 'quizzes_completed' then
            (select count(*) from public.study_activity
              where user_id = v_uid and kind = 'quiz_completed') >= (v_ach.criteria ->> 'count')::int
          when 'high_quiz_scores' then
            (select count(*) from public.quiz_attempts
              where user_id = v_uid and percent >= (v_ach.criteria ->> 'min_percent')::numeric)
              >= (v_ach.criteria ->> 'count')::int
          when 'reading_minutes' then
            (select coalesce(sum(minutes), 0) from public.study_activity
              where user_id = v_uid and kind = 'reading') >= (v_ach.criteria ->> 'minutes')::int
          when 'sessions_completed' then
            (select count(*) from public.study_activity
              where user_id = v_uid and kind = 'session_completed') >= (v_ach.criteria ->> 'count')::int
          when 'materials_uploaded' then
            (select count(*) from public.materials where user_id = v_uid) >= (v_ach.criteria ->> 'count')::int
          when 'plan_completed' then
            exists (select 1 from public.study_plans where user_id = v_uid and status = 'completed')
          else false
        end) then
      insert into public.user_achievements (user_id, achievement_id) values (v_uid, v_ach.id)
      on conflict do nothing;
      update public.profiles set xp = xp + v_ach.xp where id = v_uid;
      insert into public.notifications (user_id, kind, title, body, link)
      values (v_uid, 'achievement', 'Achievement unlocked: ' || v_ach.name, v_ach.description, '/achievements');
      v_new_achievements := v_new_achievements || jsonb_build_object('code', v_ach.code, 'name', v_ach.name, 'xp', v_ach.xp);
    end if;
  end loop;

  if v_xp > 0 then
    update public.profiles set xp = xp + v_xp where id = v_uid;
  end if;

  return jsonb_build_object(
    'recorded', true,
    'xp_awarded', v_xp,
    'qualifies_for_streak', v_qualifies,
    'current_streak', v_streak.current_streak,
    'longest_streak', v_streak.longest_streak,
    'new_achievements', v_new_achievements
  );
end;
$$;
revoke execute on function public.record_study_activity(public.activity_kind, integer, uuid, uuid) from public, anon;
grant execute on function public.record_study_activity(public.activity_kind, integer, uuid, uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- Fixed-window rate limiting. Keys are namespaced by the caller's id so a client
-- cannot exhaust another user's bucket. Returns true when the call is allowed.
-- ---------------------------------------------------------------------------
create or replace function public.check_rate_limit(p_key text, p_limit integer, p_window_seconds integer)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_key text := coalesce(auth.uid()::text, 'service') || ':' || left(p_key, 100);
  v_window timestamptz := to_timestamp(floor(extract(epoch from now()) / p_window_seconds) * p_window_seconds);
  v_count integer;
begin
  if p_limit < 1 or p_window_seconds < 1 then
    raise exception 'invalid rate limit parameters' using errcode = '22023';
  end if;
  insert into public.rate_limit_buckets as b (key, window_start, count)
  values (v_key, v_window, 1)
  on conflict (key, window_start) do update set count = b.count + 1
  returning count into v_count;

  -- Opportunistic cleanup of stale windows.
  if random() < 0.01 then
    delete from public.rate_limit_buckets where window_start < now() - interval '1 day';
  end if;
  return v_count <= p_limit;
end;
$$;
revoke execute on function public.check_rate_limit(text, integer, integer) from public, anon;
grant execute on function public.check_rate_limit(text, integer, integer) to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- Quiz review: answers & explanations become visible only after submission.
-- ---------------------------------------------------------------------------
create or replace function public.get_attempt_review(p_attempt_id uuid)
returns table (
  question_id uuid, question_position integer, question_type public.question_type, prompt text, options jsonb,
  correct_answer jsonb, explanation text, topic text, source_material_id uuid, source_page integer,
  answer jsonb, is_correct boolean, points numeric, points_awarded numeric, feedback text
)
language sql
stable
security definer
set search_path = ''
as $$
  select q.id, q.position, q.type, q.prompt, q.options, q.correct_answer, q.explanation, q.topic,
         q.source_material_id, q.source_page, a.answer, a.is_correct, q.points, a.points_awarded, a.feedback
  from public.quiz_attempts t
  join public.quiz_questions q on q.quiz_id = t.quiz_id and q.user_id = t.user_id
  left join public.quiz_answers a on a.attempt_id = t.id and a.question_id = q.id
  where t.id = p_attempt_id
    and t.user_id = auth.uid()
    and t.status in ('submitted', 'graded')
  order by q.position;
$$;
revoke execute on function public.get_attempt_review(uuid) from public, anon;
grant execute on function public.get_attempt_review(uuid) to authenticated;

-- ===== 20261113000004_storage_and_seed.sql =====
-- Private storage for uploaded learning materials.
-- Object path convention: {user_id}/{material_id}/{sanitised_filename}
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'materials', 'materials', false, 104857600, -- 100 MB hard ceiling; plan limits enforced server-side
  array[
    'application/pdf',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'text/plain'
  ]
)
on conflict (id) do update
  set public = excluded.public,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

create policy "materials_objects_select_own" on storage.objects for select to authenticated
  using (bucket_id = 'materials' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy "materials_objects_insert_own" on storage.objects for insert to authenticated
  with check (bucket_id = 'materials' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy "materials_objects_update_own" on storage.objects for update to authenticated
  using (bucket_id = 'materials' and (storage.foldername(name))[1] = (select auth.uid())::text)
  with check (bucket_id = 'materials' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy "materials_objects_delete_own" on storage.objects for delete to authenticated
  using (bucket_id = 'materials' and (storage.foldername(name))[1] = (select auth.uid())::text);

