-- ===== 20261113000005_dashboard_stats.sql =====
-- Dashboard aggregates computed from stored activity (no demo data).
-- SECURITY INVOKER: runs with the caller's privileges, so RLS scopes every row.
create or replace function public.dashboard_stats()
returns jsonb
language plpgsql
stable
security invoker
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_tz text;
  v_today date;
  v_result jsonb;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  select timezone into v_tz from public.profiles where id = v_uid;
  begin
    v_today := (now() at time zone coalesce(v_tz, 'UTC'))::date;
  exception when others then
    v_today := (now() at time zone 'UTC')::date;
  end;

  select jsonb_build_object(
    'today', v_today,
    'materials_total', (select count(*) from public.materials where user_id = v_uid),
    'materials_ready', (select count(*) from public.materials where user_id = v_uid and status = 'ready'),
    'materials_processing', (select count(*) from public.materials
                              where user_id = v_uid and status not in ('ready', 'failed')),
    'overall_completion', coalesce((
        select round(avg(coalesce(rp.percent_complete, 0)), 1)
        from public.materials m
        left join public.reading_progress rp on rp.material_id = m.id and rp.user_id = v_uid
        where m.user_id = v_uid), 0),
    'avg_quiz_score', (select round(avg(percent), 1) from public.quiz_attempts
                        where user_id = v_uid and status in ('submitted', 'graded') and percent is not null),
    'quizzes_completed', (select count(*) from public.quiz_attempts
                           where user_id = v_uid and status in ('submitted', 'graded')),
    'total_study_minutes', (select coalesce(sum(minutes), 0) from public.study_activity where user_id = v_uid),
    'today_minutes', (select coalesce(sum(minutes), 0) from public.study_activity
                       where user_id = v_uid and activity_date = v_today),
    'tasks_today_total', (select count(*) from public.study_tasks t
                           join public.study_sessions s on s.id = t.session_id
                           where t.user_id = v_uid and s.scheduled_date = v_today),
    'tasks_today_done', (select count(*) from public.study_tasks t
                          join public.study_sessions s on s.id = t.session_id
                          where t.user_id = v_uid and s.scheduled_date = v_today and t.status = 'completed'),
    'week', (
      select jsonb_agg(jsonb_build_object(
               'date', d::date,
               'minutes', coalesce(a.minutes, 0),
               'qualified', coalesce(a.qualified, false)) order by d)
      from generate_series(v_today - 6, v_today, interval '1 day') as d
      left join (
        select activity_date, sum(minutes) as minutes, bool_or(qualifies_for_streak) as qualified
        from public.study_activity
        where user_id = v_uid and activity_date between v_today - 6 and v_today
        group by activity_date
      ) a on a.activity_date = d::date
    ),
    'streak', (select jsonb_build_object('current_streak', current_streak, 'longest_streak', longest_streak,
                                         'last_qualifying_date', last_qualifying_date)
               from public.study_streaks where user_id = v_uid),
    'xp', (select xp from public.profiles where id = v_uid)
  ) into v_result;

  return v_result;
end;
$$;
revoke execute on function public.dashboard_stats() from public, anon;
grant execute on function public.dashboard_stats() to authenticated;

-- ===== 20261114000001_processing_queue.sql =====
-- Phase 2: document processing queue.

alter table public.materials
  add column pages_are_estimated boolean not null default false,
  add column processing_warning text,
  add column ocr_page_count integer not null default 0 check (ocr_page_count >= 0);

alter table public.document_processing_jobs
  add column state jsonb not null default '{}'::jsonb;

-- At most one active job per material.
create unique index processing_jobs_one_active_per_material
  on public.document_processing_jobs (material_id)
  where status in ('queued', 'running');

-- Atomically claims the next due job (or a running job whose lease expired) using
-- SKIP LOCKED, so concurrent workers never process the same job.
create or replace function public.claim_processing_job(
  p_worker text,
  p_user_id uuid default null,
  p_lease_seconds integer default 300
)
returns setof public.document_processing_jobs
language plpgsql
security definer
set search_path = ''
as $$
begin
  return query
  update public.document_processing_jobs j
     set status = 'running',
         locked_at = now(),
         locked_by = left(p_worker, 100),
         started_at = coalesce(j.started_at, now())
   where j.id = (
     select q.id
       from public.document_processing_jobs q
      where ((q.status = 'queued' and q.run_after <= now())
          or (q.status = 'running' and q.locked_at < now() - make_interval(secs => p_lease_seconds)))
        and (p_user_id is null or q.user_id = p_user_id)
      order by q.run_after, q.created_at
      for update skip locked
      limit 1
   )
  returning j.*;
end;
$$;
revoke execute on function public.claim_processing_job(text, uuid, integer) from public, anon, authenticated;
grant execute on function public.claim_processing_job(text, uuid, integer) to service_role;

-- Library listing helper: which plans use each material (owner-scoped through RLS).
create index if not exists study_plan_materials_material_user_idx on public.study_plan_materials (material_id, user_id);

-- ===== 20261115000001_planning_and_retrieval.sql =====
-- Phase 3: AI analysis, study planning and material-grounded retrieval.

-- ---------------------------------------------------------------------------
-- Retrieval: full-text search over extracted pages (RLS applies: invoker).
-- ---------------------------------------------------------------------------
alter table public.material_pages
  add column search tsvector generated always as (to_tsvector('english', coalesce(content, ''))) stored;
create index material_pages_search_idx on public.material_pages using gin (search);

create or replace function public.search_material_pages(
  p_material_ids uuid[],
  p_query text,
  p_limit integer default 6
)
returns table (material_id uuid, page_number integer, content text, rank real)
language sql
stable
security invoker
set search_path = ''
as $$
  with q as (select websearch_to_tsquery('english', left(p_query, 500)) as t)
  select p.material_id, p.page_number, p.content, ts_rank_cd(p.search, q.t) as rank
  from public.material_pages p, q
  where p.material_id = any (p_material_ids)
    and numnode(q.t) > 0
    and p.search @@ q.t
  order by rank desc, p.page_number
  limit least(greatest(p_limit, 1), 20);
$$;
revoke execute on function public.search_material_pages(uuid[], text, integer) from public, anon;
grant execute on function public.search_material_pages(uuid[], text, integer) to authenticated, service_role;

-- Where a section came from (bookmarks, headings, typography or AI analysis).
alter table public.document_sections
  add column source text not null default 'structure' check (source in ('structure', 'ai'));

-- ---------------------------------------------------------------------------
-- Plans: created and rescheduled atomically (SECURITY INVOKER -> RLS applies,
-- composite FKs guarantee every referenced row belongs to the caller).
-- ---------------------------------------------------------------------------
create or replace function public.create_study_plan(p jsonb)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_plan uuid := gen_random_uuid();
  v_session jsonb;
  v_session_id uuid;
  v_task jsonb;
  v_i integer := 0;
  v_j integer;
begin
  if v_uid is null then raise exception 'not authenticated' using errcode = '42501'; end if;

  insert into public.study_plans (id, user_id, title, mode, status, start_date, deadline, daily_minutes, study_days,
                                  preferred_time, workload, generation_meta)
  values (v_plan, v_uid, p ->> 'title', (p ->> 'mode')::public.plan_mode, 'active', (p ->> 'start_date')::date,
          (p ->> 'deadline')::date, (p ->> 'daily_minutes')::int,
          array(select jsonb_array_elements_text(p -> 'study_days')::smallint),
          p ->> 'preferred_time', coalesce((p ->> 'workload')::public.workload_preference, 'balanced'),
          coalesce(p -> 'meta', '{}'::jsonb));

  insert into public.study_plan_materials (plan_id, material_id, user_id, position)
  select v_plan, m.value::uuid, v_uid, m.ordinality - 1
  from jsonb_array_elements_text(p -> 'material_ids') with ordinality as m(value, ordinality);

  for v_session in select * from jsonb_array_elements(p -> 'sessions') loop
    v_session_id := gen_random_uuid();
    insert into public.study_sessions (id, plan_id, user_id, scheduled_date, starts_at, planned_minutes, kind, title, objectives)
    values (v_session_id, v_plan, v_uid, (v_session ->> 'date')::date, (v_session ->> 'starts_at')::timestamptz,
            (v_session ->> 'minutes')::int, (v_session ->> 'kind')::public.session_kind, v_session ->> 'title',
            array(select jsonb_array_elements_text(coalesce(v_session -> 'objectives', '[]'::jsonb))));
    v_j := 0;
    for v_task in select * from jsonb_array_elements(coalesce(v_session -> 'tasks', '[]'::jsonb)) loop
      insert into public.study_tasks (session_id, plan_id, user_id, material_id, section_id, position, title,
                                      start_page, end_page, estimated_minutes)
      values (v_session_id, v_plan, v_uid, (v_task ->> 'material_id')::uuid, (v_task ->> 'section_id')::uuid, v_j,
              v_task ->> 'title', (v_task ->> 'start_page')::int, (v_task ->> 'end_page')::int,
              coalesce((v_task ->> 'minutes')::int, 0));
      v_j := v_j + 1;
    end loop;
    v_i := v_i + 1;
  end loop;

  if v_i = 0 then raise exception 'a plan needs at least one session' using errcode = '22023'; end if;
  return v_plan;
end;
$$;
revoke execute on function public.create_study_plan(jsonb) from public, anon;
grant execute on function public.create_study_plan(jsonb) to authenticated;

-- Applies an approved reschedule: unfinished sessions are marked missed/rescheduled,
-- new sessions are created and their (existing) tasks are moved into them.
-- Completed work is never touched.
create or replace function public.apply_plan_reschedule(p_plan_id uuid, p jsonb)
returns integer
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_session jsonb;
  v_new uuid;
  v_task_id text;
  v_pos integer;
  v_count integer := 0;
  v_moved integer;
begin
  if v_uid is null then raise exception 'not authenticated' using errcode = '42501'; end if;
  if not exists (select 1 from public.study_plans where id = p_plan_id and user_id = v_uid and status = 'active') then
    raise exception 'plan not found' using errcode = '22023';
  end if;

  -- Old open sessions: past ones become "missed", future ones "rescheduled".
  update public.study_sessions
     set status = case when scheduled_date < (p ->> 'today')::date then 'missed'::public.session_status
                       else 'rescheduled'::public.session_status end
   where plan_id = p_plan_id and user_id = v_uid and status in ('scheduled', 'in_progress')
     and id in (select (jsonb_array_elements_text(p -> 'replace_session_ids'))::uuid);

  for v_session in select * from jsonb_array_elements(p -> 'sessions') loop
    v_new := gen_random_uuid();
    insert into public.study_sessions (id, plan_id, user_id, scheduled_date, starts_at, planned_minutes, kind, title,
                                       objectives, rescheduled_from)
    values (v_new, p_plan_id, v_uid, (v_session ->> 'date')::date, (v_session ->> 'starts_at')::timestamptz,
            (v_session ->> 'minutes')::int, (v_session ->> 'kind')::public.session_kind, v_session ->> 'title',
            array(select jsonb_array_elements_text(coalesce(v_session -> 'objectives', '[]'::jsonb))),
            (v_session ->> 'rescheduled_from')::uuid);
    v_pos := 0;
    for v_task_id in select jsonb_array_elements_text(coalesce(v_session -> 'task_ids', '[]'::jsonb)) loop
      update public.study_tasks
         set session_id = v_new, position = v_pos
       where id = v_task_id::uuid and plan_id = p_plan_id and user_id = v_uid and status <> 'completed';
      get diagnostics v_moved = row_count;
      if v_moved = 0 then raise exception 'task % cannot be moved', v_task_id using errcode = '22023'; end if;
      v_pos := v_pos + 1;
    end loop;
    v_count := v_count + 1;
  end loop;

  update public.study_plans
     set version = version + 1,
         deadline = greatest(deadline, coalesce((p ->> 'deadline')::date, deadline))
   where id = p_plan_id;

  return v_count;
end;
$$;
revoke execute on function public.apply_plan_reschedule(uuid, jsonb) from public, anon;
grant execute on function public.apply_plan_reschedule(uuid, jsonb) to authenticated;

-- ===== 20261116000001_reading_room.sql =====
-- Phase 4: Reading Room.

-- Reading progress is saved through one function so concurrent saves (several tabs,
-- sendBeacon on close) merge instead of overwriting each other.
create or replace function public.save_reading_progress(
  p_material_id uuid,
  p_current_page integer,
  p_scroll_offset real,
  p_pages_read integer[],
  p_seconds integer
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_page_count integer;
  v_old_seconds integer;
  v_row public.reading_progress%rowtype;
  v_pages integer[];
  v_completed uuid[];
  v_new_minutes integer;
  v_seconds integer := greatest(0, least(coalesce(p_seconds, 0), 300)); -- at most 5 minutes per save
begin
  if v_uid is null then raise exception 'not authenticated' using errcode = '42501'; end if;
  select page_count into v_page_count from public.materials where id = p_material_id and user_id = v_uid and status = 'ready';
  if not found then raise exception 'material not found' using errcode = '22023'; end if;
  v_page_count := greatest(coalesce(v_page_count, 1), 1);

  select total_seconds into v_old_seconds from public.reading_progress where user_id = v_uid and material_id = p_material_id;
  v_old_seconds := coalesce(v_old_seconds, 0);

  insert into public.reading_progress (user_id, material_id, current_page, scroll_offset, pages_read, total_seconds, last_read_at)
  values (v_uid, p_material_id, 1, 0, '{}', 0, now())
  on conflict (user_id, material_id) do nothing;

  select * into v_row from public.reading_progress where user_id = v_uid and material_id = p_material_id for update;

  v_pages := array(
    select distinct p from unnest(v_row.pages_read || coalesce(p_pages_read, '{}')) as p
    where p between 1 and v_page_count order by p
  );

  v_completed := array(
    select s.id from public.document_sections s
    where s.material_id = p_material_id and s.user_id = v_uid
      and not exists (select 1 from public.document_sections c where c.parent_id = s.id)
      and not exists (
        select 1 from generate_series(s.start_page, least(s.end_page, v_page_count)) g where g <> all (v_pages)
      )
  );

  update public.reading_progress
     set current_page = least(greatest(coalesce(p_current_page, current_page), 1), v_page_count),
         scroll_offset = least(greatest(coalesce(p_scroll_offset, 0), 0), 1),
         pages_read = v_pages,
         completed_section_ids = v_completed,
         percent_complete = round(cardinality(v_pages)::numeric * 100 / v_page_count, 2),
         total_seconds = total_seconds + v_seconds,
         last_read_at = now()
   where id = v_row.id
  returning * into v_row;

  update public.materials set last_opened_at = now() where id = p_material_id;

  -- Whole reading minutes newly crossed count as study activity (XP only, no streak).
  v_new_minutes := (v_row.total_seconds / 60) - (v_old_seconds / 60);
  if v_new_minutes > 0 then
    perform public.record_study_activity('reading', v_new_minutes, p_material_id, null);
  end if;

  return jsonb_build_object(
    'percent', v_row.percent_complete,
    'pages_read', cardinality(v_pages),
    'total_seconds', v_row.total_seconds,
    'completed_sections', cardinality(v_completed)
  );
end;
$$;
revoke execute on function public.save_reading_progress(uuid, integer, real, integer[], integer) from public, anon;
grant execute on function public.save_reading_progress(uuid, integer, real, integer[], integer) to authenticated;

